// micropython
ACMsg.MPY_MICROPYTHON_MODULE = "Micropython module: access and control MicroPython internals.";
ACMsg.MPY_MICROPYTHON_CONST = "Declare that the expression is a constant so the compiler can optimise it. Typical use: from micropython import const; CONST_X = const(123); CONST_Y = const(2 * CONST_X + 1). Constants declared this way are still accessible as global variables from outside the module they are declared in. If a constant name begins with '_' then it is hidden (not available as a global variable) and does not take up any memory during execution. const() is recognised directly by the MicroPython parser and is provided mainly so scripts can run under both CPython and MicroPython using the same pattern.";
ACMsg.MPY_MICROPYTHON_OPT_LEVEL = "Get or set the optimisation level used for subsequent compilation. If level is provided, this sets it and returns None; otherwise it returns the current optimisation level. The optimisation level controls: assertions (level 0: enabled and compiled into bytecode; level 1+: not compiled); the built-in __debug__ variable (level 0: True; level 1+: False); and source-code line numbers stored with bytecode (levels 0/1/2: stored so exceptions can report the line number; level 3+: not stored). The default optimisation level is usually 0.";
ACMsg.MPY_MICROPYTHON_OPT_LEVEL = "If level is provided, set the optimisation level for subsequent compilation of scripts and return None. If level is not provided, return the current optimisation level. The optimisation level controls: assertions (level 0: assertion statements are enabled and compiled into bytecode; level 1 and higher: assertions are not compiled); built-in __debug__ (level 0: expands to True; level 1 and higher: expands to False); and source-code line numbers (levels 0, 1 and 2: line numbers are stored with the bytecode so exceptions can report where they occurred; level 3 and higher: line numbers are not stored). The default optimisation level is usually 0.";
ACMsg.MPY_MICROPYTHON_MEM_INFO = "Print information about currently used memory. If the optional verbose argument is given then extra information is printed. The exact output is port/implementation dependent but typically includes the amount of stack and heap used; in verbose mode it may print the entire heap showing which blocks are used and which are free.";
ACMsg.MPY_MICROPYTHON_QSTR_INFO = "Print information about currently interned strings (qstrs). If the optional verbose argument is given then extra information is printed. The exact output is port/implementation dependent but typically includes the number of interned strings and the amount of RAM they use; in verbose mode it prints the names of all RAM-interned strings.";
ACMsg.MPY_MICROPYTHON_STACK_USE = "Return an integer representing the current amount of stack that is being used. The absolute value is usually not very useful; it is intended to compute differences in stack usage at different points.";
ACMsg.MPY_MICROPYTHON_HEAP_LOCK = "Lock the heap. When locked, no memory allocation can occur and a MemoryError will be raised if any heap allocation is attempted. heap_lock() can be nested (called multiple times) which increases an internal lock depth; heap_unlock() must be called the same number of times to make the heap available again. If the REPL becomes active with the heap locked then it will be forcefully unlocked.";
ACMsg.MPY_MICROPYTHON_HEAP_UNLOCK = "Unlock the heap (nestable). Returns the current lock depth after unlocking; 0 means the heap is not locked.";
ACMsg.MPY_MICROPYTHON_HEAP_LOCKED = "Return the current heap lock depth as a non-negative integer (0 means the heap is not locked). Note: heap_locked() is not enabled on most ports by default and may require a build option.";
ACMsg.MPY_MICROPYTHON_KBD_INTR = "Set the character code that will raise a KeyboardInterrupt exception. By default this is 3 during script execution, corresponding to Ctrl-C. Passing -1 disables capture of Ctrl-C; passing 3 restores it. This can be used to prevent capturing Ctrl-C on the incoming stream of characters that is usually used for the REPL, if that stream is used for other purposes.";
ACMsg.MPY_MICROPYTHON_SCHEDULE = "Schedule the function func to be executed \"very soon\". The function receives arg as its single argument. \"Very soon\" means MicroPython will try to execute it at the earliest possible time while remaining efficient, and subject to these conditions: a scheduled function never preempts another scheduled function; scheduled functions run between bytecode opcodes, so fundamental Python operations (like appending to a list) are atomic; and a port may define critical regions where scheduled functions will not run (they may be scheduled there but will only execute once the region is exited\u2014an example is a preempting IRQ). A common use is to schedule a callback from a preempting IRQ: this avoids IRQ restrictions (such as the heap being locked) by deferring work. On multi-threaded ports, behavior depends on the Global Interpreter Lock (GIL): with GIL enabled, the scheduled function can preempt any thread and run in its context; with GIL disabled, it only preempts the main thread. Note: if schedule() is called from a preempting IRQ where allocation is not allowed, and the callback passed is a bound method, passing it directly can fail because creating a bound-method reference allocates; a typical workaround is to create and store the method reference in the class constructor and schedule that stored reference. There is a finite queue for scheduled callbacks and schedule() raises RuntimeError if the queue is full.";
ACMsg.MPY_MICROPYTHON_RINGIO = "RingIO provides a fixed-size ring buffer for bytes with a stream interface, comparable to a FIFO-like variant of io.BytesIO. You can construct it with an integer size (it will allocate a suitable internal buffer) or pass an existing buffer-protocol object such as a bytearray to use it in-place. The classic ring buffer algorithm is used and one byte is reserved for tracking: when initialised with an integer size this overhead is accounted for (e.g. RingIO(16) allocates 17 bytes internally so it can hold 16 bytes), but when you pass a pre-allocated buffer, one byte less than its original length is available for storage (e.g. RingIO(bytearray(16)) holds 15 bytes). A RingIO instance can be IRQ/thread safe when used to pass data in a single direction (for example, written in an IRQ and read in non-IRQ code, or the reverse). This does not hold if you write to the same instance from both IRQ and non-IRQ contexts, which can cause data corruption.";
ACMsg.MPY_MICROPYTHON_RINGIO_ANY = "Return an integer counting the number of bytes that can be read. Returns: int.";
ACMsg.MPY_MICROPYTHON_RINGIO_READ = "Read available bytes (non-blocking). If nbytes is specified then read at most that many bytes, otherwise read as much as possible. Returns: a bytes object (empty bytes if no data is available)." ;
ACMsg.MPY_MICROPYTHON_RINGIO_READLINE = "Read a line ending in a newline character (\n) or return if one exists in the buffer; otherwise return available bytes in the buffer. If nbytes is specified then read at most that many bytes. Returns: bytes.";
ACMsg.MPY_MICROPYTHON_RINGIO_READINTO = "Read available bytes into buf. If nbytes is specified then read at most that many bytes, otherwise read at most len(buf) bytes. Returns: int (number of bytes read into buf)." ;
ACMsg.MPY_MICROPYTHON_RINGIO_WRITE = "Non-blocking write of bytes from buf into the ring buffer, limited by the available space in the ring buffer. Returns: int (number of bytes written)." ;
ACMsg.MPY_MICROPYTHON_RINGIO_CLOSE = "No-op provided as part of the standard stream interface; has no effect on the data in the ring buffer." ;
ACMsg.MPY_MICROPYTHON_NATIVE_DECORATOR = "Compile the decorated function to native machine code instead of bytecode. Often faster, but uses more memory and has limitations (e.g. some Python features are restricted). Availability depends on the port/firmware.";
ACMsg.MPY_MICROPYTHON_VIPER_DECORATOR = "Compile using the Viper emitter for higher performance, especially for integer/bit operations. Uses special Viper-native types and is less Python-compliant. Availability depends on the port/firmware.";
ACMsg.MPY_MICROPYTHON_ASM_THUMB_DECORATOR = "Define an inline assembler function for ARM Thumb/Thumb-2 targets. The function body uses MicroPython's assembler DSL. Only available on supported ARM builds.";
ACMsg.MPY_MICROPYTHON_ASM_XTENSA_DECORATOR = "Define an inline assembler function for Xtensa targets (e.g. some ESP8266/ESP32 builds). Only available when the firmware enables the Xtensa inline assembler.";
ACMsg.MPY_MICROPYTHON_ASM_RV32_DECORATOR ="Define an inline assembler function for 32-bit RISC-V targets (RV32) when enabled by the port/firmware (e.g. some rp2 configurations in RISC-V mode).";

// bluetooth
ACMsg.MPY_BLUETOOTH_BLE = "Low-level BLE interface. <b>bluetooth.BLE()</b> returns the singleton driver object. Returns: <b>BLE</b>.";
ACMsg.MPY_BLUETOOTH_BLE_ACTIVE = "Enable/disable the BLE radio (optional arg) and return current state. The radio must be active before using other BLE methods. Returns: <b>bool</b>.";
ACMsg.MPY_BLUETOOTH_BLE_CONFIG = "Get/set BLE configuration. Query with <b>config('param')</b>, set with keywords <b>config(param=value,...)</b>. Supported params include <b>'mac'</b>, <b>'addr_mode'</b>, <b>'gap_name'</b>, <b>'rxbuf'</b>, <b>'mtu'</b>, <b>'bond'</b>, <b>'mitm'</b>, <b>'io'</b>, <b>'le_secure'</b>.";
ACMsg.MPY_BLUETOOTH_BLE_GAP_ADVERTISE = "Start advertising with interval in microseconds (rounded down to nearest 625\u00b5s). Stop advertising with <b>interval_us=None</b>. <b>adv_data</b>/<b>resp_data</b> must support buffer protocol; passing <b>None</b> reuses previous payload; use <b>b''</b> to clear.";
ACMsg.MPY_BLUETOOTH_BLE_GAP_CONNECT = "Connect to a peripheral by address (use addr_type from scan). Cancel an outstanding attempt with <b>gap_connect(None)</b>. Success raises <b>_IRQ_PERIPHERAL_CONNECT</b>; cancel/disconnect raises <b>_IRQ_PERIPHERAL_DISCONNECT</b>.";
ACMsg.MPY_BLUETOOTH_BLE_GAP_DISCONNECT = "Disconnect a connected peer (central or peripheral, depending on role). Raises <b>_IRQ_PERIPHERAL_DISCONNECT</b> or <b>_IRQ_CENTRAL_DISCONNECT</b>. Returns <b>True</b> if handle was connected, else <b>False</b>. Returns: <b>bool</b>.";
ACMsg.MPY_BLUETOOTH_BLE_GAP_PAIR = "Initiate pairing with remote device. Ensure <b>io</b>, <b>mitm</b>, <b>le_secure</b>, <b>bond</b> are configured first. On success emits <b>_IRQ_ENCRYPTION_UPDATE</b>.";
ACMsg.MPY_BLUETOOTH_BLE_GAP_PASSKEY = "Respond to a <b>_IRQ_PASSKEY_ACTION</b> event (passkey I/O). Action determines whether to input, display, or confirm numeric comparison.";
ACMsg.MPY_BLUETOOTH_BLE_GAP_SCAN = "Scan for <b>duration_ms</b> (0 = indefinitely, None = stop). Configure duty cycle with <b>interval_us</b>/<b>window_us</b>. Emits <b>_IRQ_SCAN_RESULT</b> with (<b>addr_type</b>, <b>addr</b>, <b>adv_type</b>, <b>rssi</b>, <b>adv_data</b>) and <b>_IRQ_SCAN_DONE</b> when finished.";
ACMsg.MPY_BLUETOOTH_BLE_GATTC_DISCOVER_CHARACTERISTICS = "Discover characteristics in handle range (optional <b>uuid</b> filter). Emits <b>_IRQ_GATTC_CHARACTERISTIC_RESULT</b> and then <b>_IRQ_GATTC_CHARACTERISTIC_DONE</b>.";
ACMsg.MPY_BLUETOOTH_BLE_GATTC_DISCOVER_DESCRIPTORS = "Discover descriptors in handle range. Emits <b>_IRQ_GATTC_DESCRIPTOR_RESULT</b> and then <b>_IRQ_GATTC_DESCRIPTOR_DONE</b>.";
ACMsg.MPY_BLUETOOTH_BLE_GATTC_DISCOVER_SERVICES = "Discover services on a connected server (optional <b>uuid</b> filter). Emits <b>_IRQ_GATTC_SERVICE_RESULT</b> and then <b>_IRQ_GATTC_SERVICE_DONE</b>.";
ACMsg.MPY_BLUETOOTH_BLE_GATTC_EXCHANGE_MTU = "Initiate ATT MTU exchange using preferred MTU set by <b>config(mtu=value)</b>. Emits <b>_IRQ_MTU_EXCHANGED</b>.";
ACMsg.MPY_BLUETOOTH_BLE_GATTC_READ = "Issue a remote read. Emits <b>_IRQ_GATTC_READ_RESULT</b> and then <b>_IRQ_GATTC_READ_DONE</b>.";
ACMsg.MPY_BLUETOOTH_BLE_GATTC_WRITE = "Issue a remote write. <b>mode=0</b> write-without-response (no event). <b>mode=1</b> write-with-response; on response emits <b>_IRQ_GATTC_WRITE_DONE</b>.";
ACMsg.MPY_BLUETOOTH_BLE_GATTS_INDICATE = "Send an indication to a connected client. If <b>data</b> is None, send current local value; otherwise send provided <b>data</b>. On ack/failure raises <b>_IRQ_GATTS_INDICATE_DONE</b>. Sent regardless of subscription status.";
ACMsg.MPY_BLUETOOTH_BLE_GATTS_NOTIFY = "Send a notification to a connected client. If <b>data</b> is None, send current local value; otherwise send provided <b>data</b>. Sent regardless of subscription status.";
ACMsg.MPY_BLUETOOTH_BLE_GATTS_READ = "Read local value for a handle (written by <b>gatts_write</b> or a remote client). Returns: <b>bytes</b>.";
ACMsg.MPY_BLUETOOTH_BLE_GATTS_REGISTER_SERVICES = "Register GATT server services/characteristics, replacing any existing. Returns a list of tuples of value handles (flattened). Note: advertising must be stopped before registering. Returns: <b>list</b>.";
ACMsg.MPY_BLUETOOTH_BLE_GATTS_SET_BUFFER = "Set internal buffer size for a value (default 20). If <b>append=True</b>, remote writes append instead of replace. When using <b>gatts_read</b>, the value is cleared after reading (useful for UART-like services).";
ACMsg.MPY_BLUETOOTH_BLE_GATTS_WRITE = "Write local value for a handle. If <b>send_update=True</b>, subscribed clients are notified/indicated depending on characteristic properties.";
ACMsg.MPY_BLUETOOTH_BLE_IRQ = "Register an IRQ callback for BLE events. Handler signature: <b>handler(event, data)</b>. Some fields in <b>data</b> are temporary <b>memoryview</b> objects valid only during the callback; copy with <b>bytes()</b> or <b>bluetooth.UUID()</b> if needed.";
ACMsg.MPY_BLUETOOTH_BLE_L2CAP_CONNECT = "Connect to a listening peer on <b>psm</b> with local MTU <b>mtu</b>. On success emits <b>_IRQ_L2CAP_CONNECT</b>, on failure emits <b>_IRQ_L2CAP_DISCONNECT</b> with non-zero status.";
ACMsg.MPY_BLUETOOTH_BLE_L2CAP_DISCONNECT = "Disconnect an active L2CAP channel identified by (<b>conn_handle</b>, <b>cid</b>).";
ACMsg.MPY_BLUETOOTH_BLE_L2CAP_LISTEN = "Listen for incoming L2CAP CoC on <b>psm</b> with local MTU <b>mtu</b>. Emits <b>_IRQ_L2CAP_ACCEPT</b> (return non-zero to reject) and <b>_IRQ_L2CAP_CONNECT</b> once accepted. Note: cannot stop listening.";
ACMsg.MPY_BLUETOOTH_BLE_L2CAP_RECVINTO = "Receive L2CAP data into <b>buf</b>. Returns number of bytes read; if <b>buf</b> is None, returns number of bytes available. Returns: <b>int</b>.";
ACMsg.MPY_BLUETOOTH_BLE_L2CAP_SEND = "Send buffer on an L2CAP channel. Returns <b>False</b> if channel is stalled; wait for <b>_IRQ_L2CAP_SEND_READY</b> before sending again. Returns: <b>bool</b>.";
ACMsg.MPY_BLUETOOTH_FLAG_AUTHENTICATED_SIGNED_WRITE = "GATT flag constant <b>_FLAG_AUTHENTICATED_SIGNED_WRITE</b> (bitmask for characteristics/descriptors). GATT flag: authenticated signed write. Returns: <b>int</b>.";
ACMsg.MPY_BLUETOOTH_FLAG_AUX_WRITE = "GATT flag constant <b>_FLAG_AUX_WRITE</b> (bitmask for characteristics/descriptors). GATT flag: auxiliary write. Returns: <b>int</b>.";
ACMsg.MPY_BLUETOOTH_FLAG_BROADCAST = "GATT flag constant <b>_FLAG_BROADCAST</b> (bitmask for characteristics/descriptors). GATT flag: broadcast. Returns: <b>int</b>.";
ACMsg.MPY_BLUETOOTH_FLAG_INDICATE = "GATT flag constant <b>_FLAG_INDICATE</b> (bitmask for characteristics/descriptors). GATT flag: indicate. Returns: <b>int</b>.";
ACMsg.MPY_BLUETOOTH_FLAG_NOTIFY = "GATT flag constant <b>_FLAG_NOTIFY</b> (bitmask for characteristics/descriptors). GATT flag: notify. Returns: <b>int</b>.";
ACMsg.MPY_BLUETOOTH_FLAG_READ = "GATT flag constant <b>_FLAG_READ</b> (bitmask for characteristics/descriptors). GATT flag: read permitted. Returns: <b>int</b>.";
ACMsg.MPY_BLUETOOTH_FLAG_READ_AUTHENTICATED = "GATT flag constant <b>_FLAG_READ_AUTHENTICATED</b> (bitmask for characteristics/descriptors). GATT flag: authenticated read required. Returns: <b>int</b>.";
ACMsg.MPY_BLUETOOTH_FLAG_READ_AUTHORIZED = "GATT flag constant <b>_FLAG_READ_AUTHORIZED</b> (bitmask for characteristics/descriptors). GATT flag: authorized read required. Returns: <b>int</b>.";
ACMsg.MPY_BLUETOOTH_FLAG_READ_ENCRYPTED = "GATT flag constant <b>_FLAG_READ_ENCRYPTED</b> (bitmask for characteristics/descriptors). GATT flag: encrypted read required. Returns: <b>int</b>.";
ACMsg.MPY_BLUETOOTH_FLAG_WRITE = "GATT flag constant <b>_FLAG_WRITE</b> (bitmask for characteristics/descriptors). GATT flag: write with response. Returns: <b>int</b>.";
ACMsg.MPY_BLUETOOTH_FLAG_WRITE_AUTHENTICATED = "GATT flag constant <b>_FLAG_WRITE_AUTHENTICATED</b> (bitmask for characteristics/descriptors). GATT flag: authenticated write required. Returns: <b>int</b>.";
ACMsg.MPY_BLUETOOTH_FLAG_WRITE_AUTHORIZED = "GATT flag constant <b>_FLAG_WRITE_AUTHORIZED</b> (bitmask for characteristics/descriptors). GATT flag: authorized write required. Returns: <b>int</b>.";
ACMsg.MPY_BLUETOOTH_FLAG_WRITE_ENCRYPTED = "GATT flag constant <b>_FLAG_WRITE_ENCRYPTED</b> (bitmask for characteristics/descriptors). GATT flag: encrypted write required. Returns: <b>int</b>.";
ACMsg.MPY_BLUETOOTH_FLAG_WRITE_NO_RESPONSE = "GATT flag constant <b>_FLAG_WRITE_NO_RESPONSE</b> (bitmask for characteristics/descriptors). GATT flag: write without response. Returns: <b>int</b>.";
ACMsg.MPY_BLUETOOTH_GATTS_ERROR_INSUFFICIENT_AUTHENTICATION = "GATTS read-request return code <b>_GATTS_ERROR_INSUFFICIENT_AUTHENTICATION</b>. Insufficient authentication. Returns: <b>int</b>.";
ACMsg.MPY_BLUETOOTH_GATTS_ERROR_INSUFFICIENT_AUTHORIZATION = "GATTS read-request return code <b>_GATTS_ERROR_INSUFFICIENT_AUTHORIZATION</b>. Insufficient authorization. Returns: <b>int</b>.";
ACMsg.MPY_BLUETOOTH_GATTS_ERROR_INSUFFICIENT_ENCRYPTION = "GATTS read-request return code <b>_GATTS_ERROR_INSUFFICIENT_ENCRYPTION</b>. Insufficient encryption. Returns: <b>int</b>.";
ACMsg.MPY_BLUETOOTH_GATTS_ERROR_READ_NOT_PERMITTED = "GATTS read-request return code <b>_GATTS_ERROR_READ_NOT_PERMITTED</b>. Read not permitted. Returns: <b>int</b>.";
ACMsg.MPY_BLUETOOTH_GATTS_ERROR_WRITE_NOT_PERMITTED = "GATTS read-request return code <b>_GATTS_ERROR_WRITE_NOT_PERMITTED</b>. Write not permitted. Returns: <b>int</b>.";
ACMsg.MPY_BLUETOOTH_GATTS_NO_ERROR = "GATTS read-request return code <b>_GATTS_NO_ERROR</b>. Read permitted / no error. Returns: <b>int</b>.";
ACMsg.MPY_BLUETOOTH_IO_CAPABILITY_DISPLAY_ONLY = "I/O capability constant for <b>config('io')</b>: <b>_IO_CAPABILITY_DISPLAY_ONLY</b>. I/O capability: display only. Returns: <b>int</b>.";
ACMsg.MPY_BLUETOOTH_IO_CAPABILITY_DISPLAY_YESNO = "I/O capability constant for <b>config('io')</b>: <b>_IO_CAPABILITY_DISPLAY_YESNO</b>. I/O capability: display with yes/no. Returns: <b>int</b>.";
ACMsg.MPY_BLUETOOTH_IO_CAPABILITY_KEYBOARD_DISPLAY = "I/O capability constant for <b>config('io')</b>: <b>_IO_CAPABILITY_KEYBOARD_DISPLAY</b>. I/O capability: keyboard and display. Returns: <b>int</b>.";
ACMsg.MPY_BLUETOOTH_IO_CAPABILITY_KEYBOARD_ONLY = "I/O capability constant for <b>config('io')</b>: <b>_IO_CAPABILITY_KEYBOARD_ONLY</b>. I/O capability: keyboard only. Returns: <b>int</b>.";
ACMsg.MPY_BLUETOOTH_IO_CAPABILITY_NO_INPUT_OUTPUT = "I/O capability constant for <b>config('io')</b>: <b>_IO_CAPABILITY_NO_INPUT_OUTPUT</b>. I/O capability: no input/output. Returns: <b>int</b>.";
ACMsg.MPY_BLUETOOTH_IRQ_CENTRAL_CONNECT = "Event code constant <b>_IRQ_CENTRAL_CONNECT</b>. Central connected to us (peripheral role). Returns: <b>int</b>.";
ACMsg.MPY_BLUETOOTH_IRQ_CENTRAL_DISCONNECT = "Event code constant <b>_IRQ_CENTRAL_DISCONNECT</b>. Central disconnected from us. Returns: <b>int</b>.";
ACMsg.MPY_BLUETOOTH_IRQ_CONNECTION_UPDATE = "Event code constant <b>_IRQ_CONNECTION_UPDATE</b>. Connection parameters updated. Returns: <b>int</b>.";
ACMsg.MPY_BLUETOOTH_IRQ_ENCRYPTION_UPDATE = "Event code constant <b>_IRQ_ENCRYPTION_UPDATE</b>. Encryption state changed (pairing/bonding). Returns: <b>int</b>.";
ACMsg.MPY_BLUETOOTH_IRQ_GATTC_CHARACTERISTIC_DONE = "Event code constant <b>_IRQ_GATTC_CHARACTERISTIC_DONE</b>. Characteristic discovery complete. Returns: <b>int</b>.";
ACMsg.MPY_BLUETOOTH_IRQ_GATTC_CHARACTERISTIC_RESULT = "Event code constant <b>_IRQ_GATTC_CHARACTERISTIC_RESULT</b>. Characteristic discovery result. Returns: <b>int</b>.";
ACMsg.MPY_BLUETOOTH_IRQ_GATTC_DESCRIPTOR_DONE = "Event code constant <b>_IRQ_GATTC_DESCRIPTOR_DONE</b>. Descriptor discovery complete. Returns: <b>int</b>.";
ACMsg.MPY_BLUETOOTH_IRQ_GATTC_DESCRIPTOR_RESULT = "Event code constant <b>_IRQ_GATTC_DESCRIPTOR_RESULT</b>. Descriptor discovery result. Returns: <b>int</b>.";
ACMsg.MPY_BLUETOOTH_IRQ_GATTC_INDICATE = "Event code constant <b>_IRQ_GATTC_INDICATE</b>. Indication received from server. Returns: <b>int</b>.";
ACMsg.MPY_BLUETOOTH_IRQ_GATTC_NOTIFY = "Event code constant <b>_IRQ_GATTC_NOTIFY</b>. Notification received from server. Returns: <b>int</b>.";
ACMsg.MPY_BLUETOOTH_IRQ_GATTC_READ_DONE = "Event code constant <b>_IRQ_GATTC_READ_DONE</b>. Remote read complete. Returns: <b>int</b>.";
