ACMsg.MPY_BLUETOOTH_IRQ_GATTC_WRITE_DONE = "Event code constant <b>_IRQ_GATTC_WRITE_DONE</b>. Remote write acknowledged (write-with-response). Returns: <b>int</b>.";
