ACMsg.MPY_BLUETOOTH_IRQ_GATTS_READ_REQUEST = "Event code constant <b>_IRQ_GATTS_READ_REQUEST</b>. A client issued a read request (STM32 only). Returns: <b>int</b>.";
ACMsg.MPY_BLUETOOTH_IRQ_GATTS_WRITE = "Event code constant <b>_IRQ_GATTS_WRITE</b>. A client wrote to a characteristic or descriptor. Returns: <b>int</b>.";
