ACMsg.MPY_BLUETOOTH_IRQ_L2CAP_ACCEPT = "Event code constant <b>_IRQ_L2CAP_ACCEPT</b>. Incoming L2CAP channel request (return non-zero to reject). Returns: <b>int</b>.";
ACMsg.MPY_BLUETOOTH_IRQ_L2CAP_CONNECT = "Event code constant <b>_IRQ_L2CAP_CONNECT</b>. L2CAP channel connected. Returns: <b>int</b>.";
ACMsg.MPY_BLUETOOTH_IRQ_L2CAP_DISCONNECT = "Event code constant <b>_IRQ_L2CAP_DISCONNECT</b>. L2CAP channel disconnected or connect failed (non-zero status). Returns: <b>int</b>.";
ACMsg.MPY_BLUETOOTH_IRQ_L2CAP_RECV = "Event code constant <b>_IRQ_L2CAP_RECV</b>. Data available on L2CAP channel. Returns: <b>int</b>.";
