ACMsg.MPY_BLUETOOTH_IRQ_PERIPHERAL_CONNECT = "Event code constant <b>_IRQ_PERIPHERAL_CONNECT</b>. Connection to a peripheral succeeded. Returns: <b>int</b>.";
ACMsg.MPY_BLUETOOTH_IRQ_PERIPHERAL_DISCONNECT = "Event code constant <b>_IRQ_PERIPHERAL_DISCONNECT</b>. Peripheral disconnected or connect cancelled/failed. Returns: <b>int</b>.";
ACMsg.MPY_BLUETOOTH_IRQ_SCAN_DONE = "Event code constant <b>_IRQ_SCAN_DONE</b>. Scan finished or stopped. Returns: <b>int</b>.";
