ACMsg.MPY_BLUETOOTH_PASSKEY_ACTION_DISPLAY = "Passkey action constant <b>_PASSKEY_ACTION_DISPLAY</b>. Display a generated 6-digit passkey. Returns: <b>int</b>.";
ACMsg.MPY_BLUETOOTH_PASSKEY_ACTION_INPUT = "Passkey action constant <b>_PASSKEY_ACTION_INPUT</b>. User should input passkey shown on remote. Returns: <b>int</b>.";
ACMsg.MPY_BLUETOOTH_PASSKEY_ACTION_NONE = "Passkey action constant <b>_PASSKEY_ACTION_NONE</b>. No passkey action. Returns: <b>int</b>.";
ACMsg.MPY_BLUETOOTH_PASSKEY_ACTION_NUMERIC_COMPARISON = "Passkey action constant <b>_PASSKEY_ACTION_NUMERIC_COMPARISON</b>. Confirm numeric comparison (accept=1 / cancel=0). Returns: <b>int</b>.";
ACMsg.MPY_BLUETOOTH_UUID = "UUID helper for services/characteristics. Accepts a 16-bit int (e.g. <b>0x2908</b>), a 2/4/16\u2011byte buffer (e.g. <b>b\"\\x08\\x29\"</b>), or a 128\u2011bit UUID string. Returns: <b>UUID</b>.";
// re
ACMsg.MPY_RE_RE = "Simple regular expression operations (subset of CPython re; also known as ure in some ports).";
ACMsg.MPY_RE_COMPILE = "Compile a regular expression and return a compiled regex object.";
ACMsg.MPY_RE_MATCH = "Compile <b>regex_str</b> and match against <b>string</b> (match starts at the beginning of the string).";
ACMsg.MPY_RE_SEARCH = "Compile <b>regex_str</b> and search <b>string</b> for the first match.";
ACMsg.MPY_RE_SUB = "Compile <b>regex_str</b>, replace matches in <b>string</b> with <b>replace</b>, and return the new string.";
ACMsg.MPY_RE_DEBUG = "Flag value: display debug information about the compiled expression (availability depends on the port).";
ACMsg.MPY_RE_REGEX_MATCH = "Match the pattern at the start of the string (or from <b>pos</b>).";
ACMsg.MPY_RE_REGEX_SEARCH = "Search for the first location where the pattern produces a match (optionally starting at <b>pos</b>).";
ACMsg.MPY_RE_REGEX_SUB = "Replace matches in a string (more efficient than module-level use when reusing the same compiled regex).";
ACMsg.MPY_RE_REGEX_SPLIT = "Split a string using this regex; returns a list of substrings.";
ACMsg.MPY_RE_MATCH_GROUP = "Return the matching (sub)string: group 0 is the whole match, 1+ are capturing groups.";
ACMsg.MPY_RE_MATCH_GROUPS = "Return a tuple of all captured group substrings (availability depends on the port).";
ACMsg.MPY_RE_MATCH_START = "Return the start index of the match (or of a specific group) in the original string.";
ACMsg.MPY_RE_MATCH_END = "Return the end index of the match (or of a specific group) in the original string.";
ACMsg.MPY_RE_MATCH_SPAN = "Return (start, end) tuple for the match (or a specific group) in the original string.";
// framebuf
ACMsg.MPY_FRAMEBUF_MODULE = "Frame buffer manipulation module (drawing into a pixel buffer for displays).";
ACMsg.MPY_FRAMEBUF_FRAMEBUFFER = "Pixel buffer that you can draw onto (pixels, lines, rectangles, ellipses, polygons, text, and blitting other frame buffers).";
ACMsg.MPY_FRAMEBUF_FRAMEBUFFER_CTOR = "Create a <b>FrameBuffer</b> over an existing <b>buffer</b> (bytes/bytearray/etc.). <b>width</b>/<b>height</b> are in pixels, <b>format</b> selects the pixel encoding (see constants), and <b>stride</b> is the number of pixels between rows (defaults to <b>width</b>). Returns: <b>FrameBuffer</b>.";
ACMsg.MPY_FRAMEBUF_FRAMEBUFFER_FILL = "Fill the entire frame buffer with color <b>c</b>.";
ACMsg.MPY_FRAMEBUF_FRAMEBUFFER_PIXEL = "If <b>c</b> is provided, set pixel (<b>x</b>, <b>y</b>) to color <b>c</b>. If <b>c</b> is omitted, return the current color value at that pixel. Returns: <b>int|None</b>.";
ACMsg.MPY_FRAMEBUF_FRAMEBUFFER_HLINE = "Draw a horizontal line starting at (<b>x</b>, <b>y</b>) with width <b>w</b> using color <b>c</b>.";
ACMsg.MPY_FRAMEBUF_FRAMEBUFFER_VLINE = "Draw a vertical line starting at (<b>x</b>, <b>y</b>) with height <b>h</b> using color <b>c</b>.";
ACMsg.MPY_FRAMEBUF_FRAMEBUFFER_LINE = "Draw a 1-pixel thick line from (<b>x1</b>, <b>y1</b>) to (<b>x2</b>, <b>y2</b>) using color <b>c</b>.";
ACMsg.MPY_FRAMEBUF_FRAMEBUFFER_RECT = "Draw a rectangle at (<b>x</b>, <b>y</b>) of size <b>w</b>×<b>h</b> using color <b>c</b>. If <b>f</b> is True, fill the rectangle; otherwise draw only the 1-pixel outline.";
ACMsg.MPY_FRAMEBUF_FRAMEBUFFER_ELLIPSE = "Draw an ellipse centered at (<b>x</b>, <b>y</b>) with radii <b>xr</b>, <b>yr</b> using color <b>c</b>. If <b>f</b> is True, fill it. Optional <b>m</b> restricts drawing to quadrants via its low 4 bits.";
ACMsg.MPY_FRAMEBUF_FRAMEBUFFER_POLY = "Draw a closed polygon at offset (<b>x</b>, <b>y</b>) from coordinate pairs in <b>coords</b> (an <b>array</b> of integers like <b>array('h', [x0, y0, x1, y1, ...])</b>) using color <b>c</b>. If <b>f</b> is True, fill it; otherwise draw the outline.";
ACMsg.MPY_FRAMEBUF_FRAMEBUFFER_TEXT = "Draw 8×8 bitmap text <b>s</b> with its top-left corner at (<b>x</b>, <b>y</b>). Optional <b>c</b> sets the color (defaults to 1).";
ACMsg.MPY_FRAMEBUF_FRAMEBUFFER_SCROLL = "Shift the frame buffer contents by (<b>xstep</b>, <b>ystep</b>). Pixels do not wrap around; old colors may remain in uncovered areas.";
ACMsg.MPY_FRAMEBUF_FRAMEBUFFER_BLIT = "Blit another frame buffer <b>fbuf</b> onto this one at (<b>x</b>, <b>y</b>). If <b>key</b> is given, that color is treated as transparent. Optional <b>palette</b> enables blitting between different formats.";
ACMsg.MPY_FRAMEBUF_MONO_VLSB = "1-bit monochrome format: bits in a byte map vertically (bit 0 near top). Returns: <b>int</b>.";
ACMsg.MPY_FRAMEBUF_MONO_HLSB = "1-bit monochrome format: bits in a byte map horizontally (bit 7 is leftmost). Returns: <b>int</b>.";
ACMsg.MPY_FRAMEBUF_MONO_HMSB = "1-bit monochrome format: bits in a byte map horizontally (bit 0 is leftmost). Returns: <b>int</b>.";
ACMsg.MPY_FRAMEBUF_RGB565 = "16-bit color format (5+6+5): red/green/blue packed into a 16-bit integer. Returns: <b>int</b>.";
ACMsg.MPY_FRAMEBUF_GS2_HMSB = "2-bit grayscale format. Returns: <b>int</b>.";
ACMsg.MPY_FRAMEBUF_GS4_HMSB = "4-bit grayscale format. Returns: <b>int</b>.";
ACMsg.MPY_FRAMEBUF_GS8 = "8-bit grayscale format. Returns: <b>int</b>.";